<?php $items = array(); foreach ( preg_split( '/\r?\n/', (string) get_theme_mod( 'kimpu_faq_items', '' ) ) as $line ) { $parts = array_map( 'trim', explode( '|', $line, 2 ) ); if ( ! empty( $parts[0] ) && isset( $parts[1] ) ) { $items[] = $parts; } } ?><section class="section <?php echo esc_attr( kimpu_homepage_section_classes( 'faq' ) ); ?>" id="faq"><div class="container content-narrow"><?php kimpu_homepage_section_header( 'faq' ); ?><?php if ( $items ) : ?><div class="faq-list"><?php foreach ( $items as $item ) : ?><details class="faq-item"><summary><?php echo esc_html( $item[0] ); ?></summary><div class="faq-answer"><?php echo wp_kses_post( wpautop( $item[1] ) ); ?></div></details><?php endforeach; ?></div><?php else : ?><p class="empty-state"><?php esc_html_e( 'Add FAQ items in the Homepage Builder using Question|Answer.', 'kimpu-multipurpose' ); ?></p><?php endif; ?></div></section>
